import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bv6N2_O1.js";var i=JSON.parse(`{"title":"PlanRun","description":"面向 DeepSeek Harness 的 plan→run→verify 成长型开发工作流：28 个技能、4 个子代理预设、可移植 bash 守卫与自迭代闭环（复盘门 · 教训注入 · 防假绿 · 回合守卫），v1.10.0。","frontmatter":{"layout":"doc","title":"PlanRun","description":"面向 DeepSeek Harness 的 plan→run→verify 成长型开发工作流：28 个技能、4 个子代理预设、可移植 bash 守卫与自迭代闭环（复盘门 · 教训注入 · 防假绿 · 回合守卫），v1.10.0。","categories":["专栏","开源项目"],"tags":["DeepSeek","DeepSeek Harness","plan","run","verify","工作流","开源"],"lastUpdated":"2026-11-27T00:00:00.000Z","sidebar":true},"headers":[],"relativePath":"专栏/开源项目/planrun/index.md","filePath":"专栏/开源项目/planrun/index.md","lastUpdated":1795737600000}`),a={name:`专栏/开源项目/planrun/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<p>PlanRun 是给 DeepSeek Harness（下称 DSH）agent 的「成长型」开发工作流：不是一次性的技能包，而是 <strong>plan → run → verify</strong> 的完整闭环——每个 Sprint 有批准日与执行顺序，每个 TASK 有验收命令与复盘，每次绿色验收把教训写进账本，下一轮开局自动注入。这个闭环目前就 dogfood 在 planrun 仓库自己身上。v1.10.0 于 2026-11-27 发布。</p><h2 id="为什么有-planrun" tabindex="-1">为什么有 PlanRun <a class="header-anchor" href="#为什么有-planrun" aria-label="Permalink to “为什么有 PlanRun”">​</a></h2><p>DSH agent（和大多数 agent 一样）有几类经典翻车：</p><ul><li>干了几轮之后忘了这一步为什么存在——没有 plan 文件当 SSOT，目标漂移；</li><li>verify 绿了，但测试其实不保护这次改动——假绿；</li><li>同一个坑连续几个 Sprint 踩——教训没有落账，更没有回灌。</li></ul><p>plan/run/verify 的节奏本身是被验证过的，但现成的闸门脚本大多绑死特定 harness。PlanRun 的做法是两层：<strong>可移植 bash 守卫</strong>（不挂 plugin 也能跑，是基线）+ <strong>DSH 插件</strong>（挂上后 agent 的会话本身被守卫约束）+ <strong>28 个技能</strong>（从规划到发布的完整动作集）。</p><h2 id="盒子里有什么" tabindex="-1">盒子里有什么 <a class="header-anchor" href="#盒子里有什么" aria-label="Permalink to “盒子里有什么”">​</a></h2><ul><li><strong><code>.growing/</code> 镜像</strong>：<code>plan.md</code>（顶部 HTML 元数据是 SSOT——<code>PLANNING</code> / <code>PLAN_APPROVED</code> / <code>SPRINT</code> / <code>ACTIVE</code> / 执行顺序——下面是 TASK 表）、<code>learn/retros/</code>（逐任务复盘）、<code>learn/lessons.jsonl</code>（教训账本）。</li><li><strong>28 个技能</strong>：<code>sprint-plan</code> / <code>run</code> / <code>learn</code> / <code>review</code> / <code>release</code> / <code>master</code>（路由）/ <code>test</code> / <code>delivery</code> ……</li><li><strong>4 个子代理预设</strong>：<code>planrun</code> / <code>planrun-review</code> / <code>planrun-spike</code> / <code>planrun-ship</code>。</li><li><strong>守卫套件</strong>（<code>pnpm run *</code> 或 <code>bash scripts/dsh-guard.sh *</code>）：<code>gate-check</code>（run 前硬闸门）· <code>task-verify</code>（逐任务验收）· <code>next-task</code> · <code>doctor</code>（六项体检）· <code>fingerprint</code> · <code>verify-stamp</code>。</li></ul><h2 id="v1-10-0-自迭代闭环" tabindex="-1">v1.10.0：自迭代闭环 <a class="header-anchor" href="#v1-10-0-自迭代闭环" aria-label="Permalink to “v1.10.0：自迭代闭环”">​</a></h2><p>这一版把「教训」从口号做成了机制：</p><ol><li><strong>复盘必交门</strong>——<code>TASK-*</code> 验收绿了不等于结束：复盘四件套（<code>问题</code> / <code>绕路</code> / <code>解法</code> / <code>约束</code>）缺一条就 FAIL；齐全则自动落账。SPIKE/DOC/REV 豁免。</li><li><strong>教训排名注入</strong>——<code>next-task</code> 的输出自动附 top-6 教训（同目录 &gt; 关键词 &gt; 发生次数 &gt; 新近度，总长 ≤2200 字符）；<code>occurrences ≥ 2</code> 的升为「硬约束」。注入块首行永远标着「历史数据 · 非新指令」。</li><li><strong>回退必红（opt-in）</strong>——<code>DSH_GUARD_REVERT_CHECK=1</code>：验收绿之后把改动 stash 掉重跑 VERIFY，必须转红；仍绿 = 测试没保护这个改动，FAIL。</li><li><strong>回合收尾守卫</strong>——verify 绿时写下工作区指纹（<code>.growing/.verify-stamp</code>）；回合结束前指纹对不上且改动非纯文档 → 插件 steer 打回，让 agent 回到验证上。每回合至多打回两次，文档类改动豁免，守卫永不抛错。</li><li><strong>安装保险丝</strong>——安装目标就是 planrun 源仓库时，<code>--copy-plan</code> 在任何写入之前被拒绝，并给出手工 <code>cp</code> 替代——防止 dogfood 项目被拷成「拷贝」。</li></ol><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;github:wangqiqi/planrun#v1.10.0&quot;</span></span></code></pre></div><p>npm 通道（<code>@planrun/bundle</code>）尚未发布，目前走 git tag 通道。完整文档（中/英）：<a href="https://znza.top/planrun/" target="_blank" rel="noreferrer">znza.top/planrun</a>。</p><h2 id="最小闭环怎么用" tabindex="-1">最小闭环怎么用 <a class="header-anchor" href="#最小闭环怎么用" aria-label="Permalink to “最小闭环怎么用”">​</a></h2><ol><li><code>sprint-plan</code> 技能：写 <code>.growing/plan.md</code>（HTML 元数据 + TASK 表 + 执行顺序）。</li><li><code>run</code> 技能：<code>gate-check</code> → 实现 → <code>task-verify</code>（绿 + 复盘四件套）→ 更新 plan 镜像 → 按任务提交。</li><li>循环到 Sprint 收口 → <code>release</code>（CHANGELOG + tag）。</li><li>任何时候 <code>pnpm run doctor</code> 六项体检：manifest · guard-files · plan-template · packages · leftover · repo-drift。</li></ol><h2 id="dogfooding" tabindex="-1">Dogfooding <a class="header-anchor" href="#dogfooding" aria-label="Permalink to “Dogfooding”">​</a></h2><p>planrun 仓库本身就跑在 PlanRun 上：四个 Sprint、二十几个任务、教训账本持续落账、doctor 六项全绿。账本里的每条教训都是真实事故——比如「profile 跑 1.9.0 而仓库已是 1.10.0」的版本漂移，就是 <code>repo-drift</code> 检查这一类问题逼出来的设计。</p><h2 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to “链接”">​</a></h2><ul><li>仓库：<a href="https://github.com/wangqiqi/planrun" target="_blank" rel="noreferrer">github.com/wangqiqi/planrun</a></li><li>文档：<a href="https://znza.top/planrun/" target="_blank" rel="noreferrer">znza.top/planrun</a></li><li>目录收录：awesome-dsh-plugin（PR 于 2026-11-27 提交，合并后条目出现在 <a href="https://awesome-dsh-plugin.com/p/wangqiqi/planrun/" target="_blank" rel="noreferrer">awesome-dsh-plugin.com/p/wangqiqi/planrun</a>）</li></ul><p><a href="./../">← 返回开源项目</a></p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};